select user_id, merchant_id, user_name, password, openid, create_time, update_time
from sys_user
where user_name = #{userName}

select user_id, merchant_id, user_name, password, openid, create_time, update_time
from sys_user
where openid = #{openid}

select user_id, merchant_id, user_name, password, openid, create_time, update_time
from sys_user
where user_id = #{userId}

select user_id, merchant_id, user_name, password, openid, create_time, update_time
from sys_user
where merchant_id = #{merchantId}
  and user_name like concat('%', #{keyword}, '%')

    and user_id not in

        #{id}


order by user_name asc
limit #{limit}
